import React from 'react';
import { fireEvent, render, screen } from '@testing-library/react';
import ExpandableSection from './ExpandableSection';

describe('ExpandableSection', () => {
  test('should render without crashing', () => {
    render(<ExpandableSection headerText="mock-header">Mocked text</ExpandableSection>);

    expect(screen.getByText('mock-header')).toBeInTheDocument();
  });

  test('should show the content on trigger click', () => {
    render(
      <ExpandableSection headerText="mock-header" triggerTestId="expandableSectionTrigger">
        Mocked text
      </ExpandableSection>
    );

    fireEvent.click(screen.getByTestId('expandableSectionTrigger'));

    expect(screen.getByText('Mocked text')).toBeInTheDocument();
  });

  test('should render without crashing with divider', () => {
    render(
      <ExpandableSection
        headerText="mock-header"
        triggerTestId="expandableSectionTrigger"
        withDivider
      >
        Mocked text
      </ExpandableSection>
    );

    fireEvent.click(screen.getByTestId('expandableSectionTrigger'));

    expect(screen.getByText('Mocked text')).toBeInTheDocument();
  });

  test('should show the content with defaultOpen prop', () => {
    render(
      <ExpandableSection headerText="mock-header" defaultOpen>
        Mocked text
      </ExpandableSection>
    );

    expect(screen.getByText('Mocked text')).toBeInTheDocument();
  });

  test('should show the content with open prop', () => {
    render(
      <ExpandableSection headerText="mock-header" open>
        Mocked text
      </ExpandableSection>
    );

    expect(screen.getByText('Mocked text')).toBeInTheDocument();
  });
});
